  "Как нарисованы значки-рисунки (эмодзи или рисунки — в настройках, «Отображение» → «Значки»); «по теме» — пиксель в киберпанке, тушь в нуаре и Японии, округлые в каваи": "How the drawn icons look (emoji or drawings — in settings, “Display” → “Icons”); “by theme” — pixel in cyberpunk, ink in noir and Japan, rounded in kawaii",
