  "Нейтральный": "Neutral",
  "По внешности": "By appearance",
  "Контур — тёмное тело и светящаяся линия цвета темы; тепловизор — тепло растекается по тёмно-синему телу; мягкий объём — тон кожи из описания, тень и свет": "Outline — dark body and a glowing line in the theme color; thermal — heat spreads over a dark-blue body; soft volume — skin tone from the description, shadow and light",
