  "Портрет в золотом кольце с тенью луны, под именем — строка хода с датой и временем, в конце вкладки — разделитель ✧": "The portrait in a golden ring with the moon’s shadow, a turn line with the date and time under the name, and a ✧ divider at the end of the tab",
