  "Картинка рядом с именем и вид самой надписи. «Авто» — как в «Рисунках темы»": "The picture next to the name and the look of the name itself. “Auto” — as in “Theme drawings”",
  "Угол вкладки": "Tab corner",
  "Рисунки во вкладке под плашками, чаще всего в правом нижнем углу. «Авто» — как в «Рисунках темы»": "Drawings in the tab under the pills, mostly in the bottom right corner. “Auto” — as in “Theme drawings”",
  "Вся карточка": "Whole card",
  "Слой поверх всей карточки: частицы, блики, дымка — сквозь него всё нажимается. «Авто» — как в «Рисунках темы»": "A layer over the whole card: particles, glints, haze — everything under it stays clickable. “Auto” — as in “Theme drawings”",
  "Чья сцена во всех местах сразу: полоса TavernOS с вкладками, шапка, имя, портрет, угол вкладки и вся карточка. «Авто» — у каждой темы своя; можно взять сцену другой темы. Картинки встают на место значков, если «Без картинок» выключено или они выбраны здесь руками. Места ниже, портрет и шапку можно поменять по отдельности": "Whose scene goes everywhere at once: the TavernOS bar with tabs, header, name, portrait, tab corner and the whole card. “Auto” — each theme has its own; you can take another theme’s scene. Pictures replace the icons if “No pictures” is off or they are picked here by hand. The places below, the portrait and the header can be changed separately",
  "Без картинок": "No pictures",
  "Всё, что встало «по теме» картинкой, уходит: рисунки темы — своими значками, рамка портрета, картинка угла шапки, печать, ярлыки, дракон, бант, пластырь, ноты и подвеска — прячутся, разделители-картинки — простой линией. Выбранное руками остаётся. Значки плашек и остальное оформление не меняются": "Everything set “by theme” as a picture goes away: theme drawings use our own icons, the portrait frame, header corner picture, seal, labels, dragon, bow, plaster, notes and pendant are hidden, picture dividers become a plain line. Anything picked by hand stays. Pill icons and the rest of the design stay the same",
  "Тушь": "Ink wash",
  "Двойная линия цвета темы, растворяющаяся к краям вкладки; мысли и «Ключевое» — полосой туши": "A double line in the theme color fading toward the tab edges; thoughts and “Key” — as a stroke of ink",
  "Кот на краю": "Cat on the edge",
  "Из-за полосы TavernOS выглядывает чёрный кот с жёлтыми глазами, обведённый цветом темы": "A black cat with yellow eyes, outlined in the theme color, peeks out from behind the TavernOS bar",
  "допуск огр": "restricted",
  "Под карточкой: «конец сцены», кто в ролях, место и время": "Under the card: “end of scene”, who's in the cast, place and time",
