  "У листа дневника свой почерк по настроению записи: моноширинный у расчёта, сжатый у напряжения, каракули у паники. «Мой шрифт» — везде шрифт дневника из настроек выше": "Each diary page has its own handwriting by the mood of the entry: monospace for calculation, compressed for tension, scrawl for panic. “My font” — the diary font from the settings above everywhere",
