  "Светлее тёмные заголовки": "Lighter dark headings",
  "В настройках и «Кастомизации» у каждой темы своя галочка (звёзды у Вампира, сердечки у Каваи, соты у Биопанка…) и свой ползунок": "In the settings and “Customization” each theme has its own checkbox (stars for Vampire, hearts for Kawaii, honeycomb for Biopunk…) and its own slider",
