  "Секрет прозвучал в словесной дуэли при том, кто его не знал: спросить, отметить ли «знает / подозревает», отметить сразу или молчать. Отметка — ваша правка: модель её увидит, текст сообщения не меняется": "A secret came out in a verbal duel in front of someone who didn't know it: ask whether to mark “knows / suspects”, mark at once, or stay silent. The mark is your edit: the model will see it, the message text doesn't change",
