  "Летопись — выжимки HUD, которые архив берёт, когда HUD вычищен из сообщений. Своя ведётся по копии чата всегда. Если HUD узнал чат не так или старые HUD остались в другом чате — выберите тот чат (или его летопись): HUD прочитает его файл, его ходы закроют пропуски своей, а ходы, которых здесь нет, архив добавит без дублей. Сам выбранный чат не меняется": "The chronicle holds HUD summaries the archive uses when the HUD has been cleared from messages. Its own is always kept from a copy of the chat. If the HUD misidentified the chat or old HUDs stayed in another chat, choose that chat (or its chronicle): the HUD will read its file, its turns will fill gaps in its own, and turns that aren't here will be added to the archive without duplicates. The chosen chat itself isn't changed",
