  "Считает HUD, а не модель: «сколько часов назад», долг сна и износ модель не просят. «Надо бы в душ» — по часам, жаре, нагрузке и близости: пот и жидкости (семя, смазка, слюна, кровь) пачкают сразу, а близость в душе, ванной или джакузи сама считается мытьём; душ и ванна берутся и из самого текста ответа, если HUD о них промолчал — только совершённое действие в авторской речи, без прямой речи, отрицаний, намерений и воспоминаний; скрытые (/hide) ходы тоже учитываются, а скачок времени сюжета («три года спустя») начинает быт заново; голод — с причиной; луна на ночи — сон той ночи; «не по погоде» — снаружи в мороз без верха или в жару в пальто; «хватит» — баланс против средней знакомой цены; долги — из флагов и расписок. Видит ли модель итог — настройка «Быт → модели» в настройках расширения («только по теме» — лишь то, о чём говорили в последних сообщениях). Вид сводки (кольца или полоски), суток (лента или циферблат) и гардероба (бирки, вешалка, список) — в «Кастомизации», раздел «Блоки: Быт»; события одного часа на ленте собираются в одну плашку со счётчиком": "The HUD counts this, not the model: «how many hours ago», sleep debt and wear aren't asked of the model. «Could use a shower» goes by hours, heat, exertion and intimacy: sweat and fluids (semen, lubrication, saliva, blood) soil at once, while intimacy in a shower, bath or jacuzzi counts as washing; showers and baths are also taken from the reply text itself if the HUD kept quiet about them — only a completed action in narration, no direct speech, negations, intentions or memories; hidden (/hide) turns count too, and a story time skip («three years later») restarts daily life; hunger comes with a reason; the moon on a night is that night's sleep; «not for the weather» means outside in frost without outerwear or in heat in a coat; «enough» is the balance against the average familiar price; debts come from flags and promissory notes. Whether the model sees the result is the «Daily life → model» setting in the extension settings («on topic only» — only what was discussed in recent messages). The summary style (rings or bars), the day (strip or dial) and the wardrobe (tags, hanger, list) are in «Customization», section «Blocks: Daily life»; events of one hour on the strip collapse into one badge with a counter",
